import * as DialogPrimitive from "@kobalte/core/dialog";
import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import type { ComponentProps, JSX, ValidComponent } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import IconCloseLine from "~icons/ri/close-line";
import type { Component } from "solid-js";

import { omit, Show } from "solid-js";
import { buttonVariants } from "./button.tsx";

const Dialog = DialogPrimitive.Root;
const DialogPortal = DialogPrimitive.Portal;

type DialogTriggerProps<T extends ValidComponent = "button"> =
  & DialogPrimitive.DialogTriggerProps<T>
  & { class?: string | undefined };

const DialogTrigger = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, DialogTriggerProps<T>>,
) => {
  return (
    <DialogPrimitive.Trigger
      data-slot="dialog-trigger"
      {...(props as DialogTriggerProps)}
    />
  );
};

type DialogCloseProps<T extends ValidComponent = "button"> =
  & DialogPrimitive.DialogCloseButtonProps<T>
  & { class?: string | undefined };

const DialogClose = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, DialogCloseProps<T>>,
) => {
  return (
    <DialogPrimitive.CloseButton
      data-slot="dialog-close"
      {...(props as DialogCloseProps)}
    />
  );
};

type DialogOverlayProps<T extends ValidComponent = "div"> =
  & DialogPrimitive.DialogOverlayProps<T>
  & { class?: string | undefined };

const DialogOverlay = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, DialogOverlayProps<T>>,
) => {
  const local = props as DialogOverlayProps;
  const rest = omit(local, "class");
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      class={cn(
        "data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 bg-black/10 duration-100 supports-backdrop-filter:backdrop-blur-xs fixed inset-0 isolate z-50",
        local.class,
      )}
      {...rest}
    />
  );
};

type DialogContentProps<T extends ValidComponent = "div"> =
  & DialogPrimitive.DialogContentProps<T>
  & {
    class?: string | undefined;
    children?: JSX.Element;
    showCloseButton?: boolean;
  };

const DialogContent = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, DialogContentProps<T>>,
) => {
  const local = props as DialogContentProps;
  const rest = omit(local, "class", "children", "showCloseButton");
  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        class={cn(
          "bg-popover text-popover-foreground data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 data-closed:zoom-out-95 data-expanded:zoom-in-95 ring-foreground/10 grid max-w-[calc(100%-2rem)] gap-4 rounded-xl p-4 text-sm ring-1 duration-100 sm:max-w-sm fixed top-1/2 left-1/2 z-50 w-full -translate-x-1/2 -translate-y-1/2 outline-none",
          local.class,
        )}
        {...rest}
      >
        {local.children}
        <Show when={local.showCloseButton ?? true}>
          <DialogPrimitive.CloseButton
            data-slot="dialog-close"
            class={cn(
              buttonVariants({ variant: "ghost", size: "icon-sm" }),
              "absolute top-2 right-2",
            )}
          >
            <IconCloseLine
            />
            <span class="sr-only">Close</span>
          </DialogPrimitive.CloseButton>
        </Show>
      </DialogPrimitive.Content>
    </DialogPortal>
  );
};

const DialogHeader: Component<ComponentProps<"div">> = (props) => {
  const rest = omit(props, "class");
  return (
    <div
      data-slot="dialog-header"
      class={cn("gap-2 flex flex-col", props.class)}
      {...rest}
    />
  );
};

type DialogFooterProps = ComponentProps<"div"> & {
  showCloseButton?: boolean;
  children?: JSX.Element;
};

const DialogFooter: Component<DialogFooterProps> = (props) => {
  const rest = omit(props, "class", "showCloseButton", "children");
  return (
    <div
      data-slot="dialog-footer"
      class={cn(
        "bg-muted/50 -mx-4 -mb-4 rounded-b-xl border-t p-4 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end",
        props.class,
      )}
      {...rest}
    >
      {props.children}
      <Show when={props.showCloseButton}>
        <DialogPrimitive.CloseButton
          class={cn(buttonVariants({ variant: "outline" }))}
        >
          Close
        </DialogPrimitive.CloseButton>
      </Show>
    </div>
  );
};

type DialogTitleProps<T extends ValidComponent = "h2"> =
  & DialogPrimitive.DialogTitleProps<T>
  & { class?: string | undefined };

const DialogTitle = <T extends ValidComponent = "h2">(
  props: PolymorphicProps<T, DialogTitleProps<T>>,
) => {
  const local = props as DialogTitleProps;
  const rest = omit(local, "class");
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      class={cn(
        "text-base leading-none font-medium font-heading",
        local.class,
      )}
      {...rest}
    />
  );
};

type DialogDescriptionProps<T extends ValidComponent = "p"> =
  & DialogPrimitive.DialogDescriptionProps<T>
  & { class?: string | undefined };

const DialogDescription = <T extends ValidComponent = "p">(
  props: PolymorphicProps<T, DialogDescriptionProps<T>>,
) => {
  const local = props as DialogDescriptionProps;
  const rest = omit(local, "class");
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      class={cn(
        "text-muted-foreground *:[a]:hover:text-foreground text-sm *:[a]:underline *:[a]:underline-offset-3",
        local.class,
      )}
      {...rest}
    />
  );
};

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};
